const state={user:null,required:false,products:[],settings:{hideOutOfStock:false},settingsVersion:1,readonly:false,view:['settings','products','offers','comments'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'overview',offerId:null,offerDraft:null,editor:null,dirty:false,busy:false,uploading:false,query:'',status:'all',category:'all',brand:'all',inventory:'all',sort:'recent',page:1,selected:new Set(),error:'',message:''};
