async function api(path,{method='GET',body,file}={}){const response=await fetch(path,{method,credentials:'same-origin',signal:AbortSignal.timeout(20000),headers:{...(file?{'Content-Type':file.type}:body?{'Content-Type':'application/json'}:{}),...(state.user?{'X-Persia-User':state.user.id}:{})},body:file|| (body?JSON.stringify(body):undefined)});const data=await response.json().catch(()=>({}));if(!response.ok){if(['sessionExpired','accountChanged'].includes(data.error)){state.user=null;state.products=[];state.editor=null;state.dirty=false;state.readonly=false;}throw Object.assign(new Error(data.error),{code:data.error||'serverError',status:response.status});}return data;}
