 main.innerHTML='<section class="adm-auth-shell"><div class="adm-auth-story"><img src="assets/persia-pasargadae-v1.webp" alt=""><p class="adm-eyebrow">PERSIA MARKET / MANAGEMENT</p><h1>'+esc(T('title'))+'</h1><p>'+esc(T('intro'))+'</p><p>'+esc(T('demo'))+'</p><a class="adm-button secondary" href="#preview">'+esc(T('returnPreview'))+'</a></div><div class="adm-auth-card"><h2>'+esc(T(setup?'setup':'login'))+'</h2><p class="adm-help">'+esc(T(setup?'ownerNote':'loginHelp'))+'</p>'+notice()+'<form id="admin-auth-form">'+(setup?field('owner-name',T('name'),'','required minlength="2" maxlength="80" autocomplete="name"'):'')+field('admin-email',T('email'),'','type="email" required maxlength="254" autocomplete="username" dir="ltr"')+field('admin-password',T('password'),'','type="password" required '+(setup?'minlength="15" ':'')+'maxlength="128" autocomplete="'+(setup?'new-password':'current-password')+'" dir="ltr"')+(setup?'<p class="adm-help">'+esc(T('passwordHint'))+'</p>'+field('admin-confirm-password',T('confirmPassword'),'','type="password" required minlength="15" maxlength="128" autocomplete="new-password" dir="ltr"'):'')+'<button class="adm-button primary" type="submit">'+esc(T(setup?'createOwner':'login'))+'</button></form>'+(state.required&&!setup?'<p class="adm-help" style="margin-top:20px"><a href="#setup">'+esc(T('setup'))+' ←</a></p>':'')+(state.user?button(T('logout'),'data-admin-logout'):'')+'</div></section>';
