function filtered(){const normalize=v=>String(v).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f\u064b-\u065f]/g,'').replace(/ي/g,'ی').replace(/ك/g,'ک');const q=normalize(state.query.trim());return state.products.filter(p=>(state.status==='all'||p.status===state.status)&&(state.category==='all'||p.category===state.category)&&(state.brand==='all'||(p.brand||'Persia Market')===state.brand)&&(state.inventory==='all'||state.inventory==='stockOut'&&p.stock===0||state.inventory==='lowStock'&&p.stock>0&&p.stock<=5||state.inventory==='discounted'&&hasDiscount(p)||state.inventory==='missingPhoto'&&p.image==='assets/product-placeholder.svg')&&(!q||normalize([...p.name,p.brand||'',p.sku,p.id].join(' ')).includes(q))).sort((a,b)=>state.sort==='nameAsc'?name(a).localeCompare(name(b),lang):state.sort==='priceAsc'?(a.cents??Infinity)-(b.cents??Infinity):state.sort==='priceDesc'?(b.cents??-Infinity)-(a.cents??-Infinity):state.sort==='stockAsc'?(a.stock??Infinity)-(b.stock??Infinity):(b.updatedAt||'').localeCompare(a.updatedAt||''));}
