 document.querySelector('#admin-result-count').textContent=number(list.length)+' '+T('items');document.querySelector('#admin-page-label').textContent=T('page')+' '+number(state.page)+' '+T('of')+' '+number(pages);document.querySelector('[data-admin-prev]').disabled=state.page<=1;document.querySelector('[data-admin-next]').disabled=state.page>=pages;
